/**
 * lib/crypto/btc-tx.ts
 * Bitcoin transaction helpers backed by bitcoinjs-lib PSBT.
 *
 * Supports:
 * - source wallets generated by NeuroWallet: legacy P2PKH (old) and native SegWit P2WPKH (new)
 * - recipient outputs: bc1q, bc1p, 3..., 1...
 *
 * Fees: the review (simulate.ts) and the signer share one vsize model and one
 * UTXO selection (planBtcTx). sendBtc signs at the fee rate the user reviewed;
 * every signing path refuses a rate above BTC_MAX_FEE_RATE_SAT_VB or a fee above
 * BTC_MAX_FEE_SHARE_PERCENT of the amount. No RBF (owner decision): inputs keep
 * the default final sequence.
 *
 * Errors carry a stable `code` (BtcTxError) that the UI maps to i18n text.
 */

import * as bitcoin from 'bitcoinjs-lib';
import * as ecc from '@bitcoinerlab/secp256k1';
import { secp256k1 } from '@noble/curves/secp256k1';
import { Buffer } from 'buffer';
import { decryptBytes } from './aes';
import { BroadcastOutcomeUnknownError } from './broadcast-error';
import { amountToDecimalString } from '@/lib/display-format';

// Без ECC-библиотеки bitcoinjs не умеет taproot: toOutputScript('bc1p…') бросает
// «No ECC Library provided» → адрес получателя считался невалидным.
bitcoin.initEccLib(ecc);

const BLOCKSTREAM = 'https://blockstream.info/api';
const MEMPOOL     = 'https://mempool.space/api';
const NETWORK     = bitcoin.networks.bitcoin;

/** Absolute fee-rate ceiling for signing, sat/vB. Above it the send is refused. */
export const BTC_MAX_FEE_RATE_SAT_VB = 500;
/** The fee may not exceed this share of the amount sent, %. */
export const BTC_MAX_FEE_SHARE_PERCENT = 50;
/** Outputs at or below this are not created (change is folded into the fee). */
export const BTC_DUST_SAT = 546n;

export type BtcErrorCode =
  | 'BTC_FEE_RATE_TOO_HIGH'
  | 'BTC_FEE_TOO_HIGH_VS_AMOUNT'
  | 'BTC_INVALID_FEE_RATE'
  | 'BTC_DUST'
  | 'BTC_NO_UTXO'
  | 'BTC_INSUFFICIENT_FUNDS'
  | 'BTC_UNSUPPORTED_SOURCE'
  | 'BTC_UTXO_FETCH_FAILED'
  | 'BTC_RAW_TX_FETCH_FAILED'
  | 'BTC_BROADCAST_REJECTED'
  // Kept for the UI map; a broadcast with no definitive answer now throws
  // BroadcastOutcomeUnknownError (broadcast-error.ts) instead.
  | 'BTC_BROADCAST_UNAVAILABLE';

export class BtcTxError extends Error {
  readonly code: BtcErrorCode;
  /** Upstream text for BTC_BROADCAST_REJECTED (node reject reason), ≤200 chars. */
  readonly detail?: string;
  constructor(code: BtcErrorCode, message: string, detail?: string) {
    super(message);
    this.name = 'BtcTxError';
    this.code = code;
    this.detail = detail;
  }
}

/** Code of a BtcTxError, also across module copies (instanceof-free). */
export function btcErrorCode(e: unknown): BtcErrorCode | null {
  const code = (e as { code?: unknown } | null)?.code;
  return typeof code === 'string' && code.startsWith('BTC_') ? (code as BtcErrorCode) : null;
}

export interface UTXO {
  txid:   string;
  vout:   number;
  value:  number; // satoshis
  status: { confirmed: boolean; block_height?: number };
}

type BtcSourceType = 'p2wpkh' | 'p2pkh';

interface BtcSigner {
  publicKey: Uint8Array;
  sign(hash: Uint8Array): Uint8Array;
}

export interface BtcTxPlan {
  utxos:        UTXO[];
  totalIn:      bigint;
  amountSat:    bigint;
  /** Paid to miners, including change at or below the dust limit. */
  fee:          bigint;
  /** Change output value; 0n when no change output is created. */
  change:       bigint;
  /** Estimated vsize the fee was computed for. */
  vbytes:       number;
  feeRateSatVb: number;
}

function signerFromPrivKey(privKey: Uint8Array): BtcSigner {
  return {
    publicKey: secp256k1.getPublicKey(privKey, true),
    sign(hash: Uint8Array): Uint8Array {
      return secp256k1.sign(hash, privKey, { lowS: true }).toCompactRawBytes();
    },
  };
}

function getSourceType(address: string): BtcSourceType {
  if (/^bc1q/i.test(address)) return 'p2wpkh';
  if (/^1/.test(address)) return 'p2pkh';
  throw new BtcTxError(
    'BTC_UNSUPPORTED_SOURCE',
    'Этот тип BTC-адреса отправителя пока не поддерживается. Создай или импортируй обычный NeuroWallet BTC-кошелёк.',
  );
}

function getOwnPayment(signer: BtcSigner, sourceType: BtcSourceType): bitcoin.Payment {
  const pubkey = Buffer.from(signer.publicKey);
  if (sourceType === 'p2wpkh') {
    return bitcoin.payments.p2wpkh({ pubkey, network: NETWORK });
  }
  return bitcoin.payments.p2pkh({ pubkey, network: NETWORK });
}

export function btcSegwitAddressFromPrivKey(privKey: Uint8Array): string {
  const signer = signerFromPrivKey(privKey);
  const payment = bitcoin.payments.p2wpkh({
    pubkey: Buffer.from(signer.publicKey),
    network: NETWORK,
  });
  if (!payment.address) throw new Error('Не удалось создать BTC SegWit-адрес.');
  return payment.address;
}

export function isValidBtcAddress(address: string): boolean {
  if (!address) return false;
  try {
    bitcoin.address.toOutputScript(address, NETWORK);
    return /^(bc1q|bc1p|1|3)/i.test(address);
  } catch {
    return false;
  }
}

export async function fetchUTXOs(address: string): Promise<UTXO[]> {
  let res: Response;
  try {
    res = await fetch(`${BLOCKSTREAM}/address/${address}/utxo`);
  } catch {
    throw new BtcTxError('BTC_UTXO_FETCH_FAILED', 'Не удалось получить UTXO (Blockstream недоступен).');
  }
  if (!res.ok) throw new BtcTxError('BTC_UTXO_FETCH_FAILED', 'Не удалось получить UTXO (Blockstream недоступен).');
  const data = await res.json() as UTXO[];
  return data.filter((u) => u.status.confirmed);
}

/** Current economy fee rate (mempool.space hourFee), sat/vB. Not capped here: signing caps it. */
export async function getBtcFeeRate(): Promise<number> {
  try {
    const res = await fetch(`${MEMPOOL}/v1/fees/recommended`);
    const data = await res.json() as { hourFee?: number };
    return Math.max(data.hourFee ?? 10, 2);
  } catch {
    return 15;
  }
}

/** Refuses a fee rate the signer must not use. */
export function assertBtcFeeRate(feeRateSatVb: number): void {
  if (!Number.isFinite(feeRateSatVb) || feeRateSatVb < 1) {
    throw new BtcTxError('BTC_INVALID_FEE_RATE', `Invalid BTC fee rate: ${feeRateSatVb} sat/vB.`);
  }
  if (feeRateSatVb > BTC_MAX_FEE_RATE_SAT_VB) {
    throw new BtcTxError(
      'BTC_FEE_RATE_TOO_HIGH',
      `BTC fee rate ${feeRateSatVb} sat/vB is above the ${BTC_MAX_FEE_RATE_SAT_VB} sat/vB cap.`,
    );
  }
}

function assertFeeShare(fee: bigint, amountSat: bigint): void {
  if (fee * 100n > amountSat * BigInt(BTC_MAX_FEE_SHARE_PERCENT)) {
    throw new BtcTxError(
      'BTC_FEE_TOO_HIGH_VS_AMOUNT',
      `BTC fee ${fee} sat is more than ${BTC_MAX_FEE_SHARE_PERCENT}% of the amount ${amountSat} sat.`,
    );
  }
}

/** Plain BTC decimal string (≤ 8 decimals) → satoshis, without float math. */
export function btcToSats(decimal: string): bigint {
  const m = /^(\d+)(?:\.(\d{0,8}))?$/.exec(decimal.trim());
  if (!m) throw new Error('Некорректная сумма.');
  return BigInt(m[1]) * 100_000_000n + BigInt((m[2] ?? '').padEnd(8, '0') || '0');
}

async function fetchRawTx(txid: string): Promise<Buffer> {
  let res: Response;
  try {
    res = await fetch(`${BLOCKSTREAM}/tx/${txid}/hex`);
  } catch {
    throw new BtcTxError('BTC_RAW_TX_FETCH_FAILED', 'Не удалось получить raw BTC transaction для подписи.');
  }
  if (!res.ok) throw new BtcTxError('BTC_RAW_TX_FETCH_FAILED', 'Не удалось получить raw BTC transaction для подписи.');
  const hex = await res.text();
  return Buffer.from(hex.trim(), 'hex');
}

/** A node answer meaning "this exact transaction is already known": not a rejection. */
const ALREADY_KNOWN_RE = /already in block chain|txn-already-in-mempool|txn-already-known|transaction already exists/i;

/**
 * Does an explorer know this txid (mempool or chain)? GET /tx/{txid}/status
 * answers 200 with {confirmed: boolean} for a known tx, 404 otherwise. Only a
 * well-formed 200 counts: a captive portal or an error page is "not known".
 */
async function btcExplorerKnowsTx(txid: string): Promise<boolean> {
  for (const base of [BLOCKSTREAM, MEMPOOL]) {
    try {
      const res = await fetch(`${base}/tx/${txid}/status`);
      if (res.status !== 200) continue;
      const body = await res.json() as { confirmed?: unknown } | null;
      if (body && typeof body === 'object' && typeof body.confirmed === 'boolean') return true;
    } catch {
      // network error / bad JSON → ask the next explorer
    }
  }
  return false;
}

/**
 * Broadcast a signed transaction. Blockstream first; on a network error, 5xx or
 * 429 the same bytes go once to mempool.space (identical txid, so a second
 * broadcast can never pay twice). Any other 4xx is the network rejecting the
 * transaction (invalid, fee too low, …): surfaced, not retried elsewhere.
 * When both explorers fail at the transport level the POST may still have
 * reached a node, so the txid is looked up: known → success; otherwise
 * BroadcastOutcomeUnknownError(txid) (the UI polls instead of re-sending).
 * Returns the txid computed from the signed bytes.
 */
export async function broadcastBtcTx(rawHex: string): Promise<string> {
  const txid = bitcoin.Transaction.fromHex(rawHex).getId();
  const endpoints = [BLOCKSTREAM, MEMPOOL];

  for (let i = 0; i < endpoints.length; i++) {
    let res: Response;
    try {
      res = await fetch(`${endpoints[i]}/tx`, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain' },
        body: rawHex,
      });
    } catch {
      continue; // network error → next endpoint
    }
    if (res.ok) return txid;

    const text = (await res.text().catch(() => '')).slice(0, 200);
    // These exact bytes are already on the network (an earlier POST whose
    // answer was lost, or a retry that rebuilt the identical transaction).
    if (ALREADY_KNOWN_RE.test(text)) return txid;
    if (res.status >= 500 || res.status === 429) continue;
    throw new BtcTxError('BTC_BROADCAST_REJECTED', 'BTC broadcast rejected: ' + text, text);
  }
  // BTC_BROADCAST_UNAVAILABLE case: no explorer gave a definitive answer.
  if (await btcExplorerKnowsTx(txid)) return txid;
  throw new BroadcastOutcomeUnknownError(txid, 'BTC broadcast outcome unknown: Blockstream and mempool.space did not answer.');
}

// ─── vsize model (shared by the review and the signer) ───────────────────────

/** vbytes of one input spent from our own address type (72-byte signature). */
const INPUT_VBYTES: Record<BtcSourceType, number> = { p2wpkh: 68, p2pkh: 148 };
/** Recipient not known yet (MAX before an address is typed): largest standard output (P2TR / P2WSH). */
const UNKNOWN_OUTPUT_VBYTES = 43;

function outputVBytes(address?: string): number {
  if (!address) return UNKNOWN_OUTPUT_VBYTES;
  try {
    const script = bitcoin.address.toOutputScript(address, NETWORK);
    return 8 + 1 + script.length; // value + script length + script
  } catch {
    return UNKNOWN_OUTPUT_VBYTES;
  }
}

function estimateTxVBytes(inputCount: number, sourceType: BtcSourceType, toAddress: string | undefined, changeAddress: string): number {
  // version 4 + locktime 4 + input count 1 + output count 1; SegWit marker+flag
  // add 2 weight units (0.5 vB), rounded up.
  const overhead = sourceType === 'p2wpkh' ? 11 : 10;
  return overhead + inputCount * INPUT_VBYTES[sourceType] + outputVBytes(toAddress) + outputVBytes(changeAddress);
}

/**
 * Greedy largest-first UTXO selection with the fee for a two-output
 * transaction. Change at or below the dust limit is not created and goes to
 * the fee (reflected in `fee`). Pure: no network, no caps.
 */
export function planBtcTx(
  available:     UTXO[],
  amountSat:     bigint,
  feeRateSatVb:  number,
  toAddress:     string | undefined,
  changeAddress: string,
): BtcTxPlan {
  const sourceType = getSourceType(changeAddress);
  if (available.length === 0) {
    throw new BtcTxError('BTC_NO_UTXO', 'Нет подтверждённых UTXO. Подожди подтверждения входящих транзакций.');
  }
  const sorted = [...available].sort((a, b) => b.value - a.value);
  const selected: UTXO[] = [];
  let totalIn = 0n;

  for (const utxo of sorted) {
    selected.push(utxo);
    totalIn += BigInt(utxo.value);

    const vbytes = estimateTxVBytes(selected.length, sourceType, toAddress, changeAddress);
    const fee = BigInt(Math.ceil(vbytes * feeRateSatVb));
    if (totalIn >= amountSat + fee) {
      const rest = totalIn - amountSat - fee;
      const change = rest > BTC_DUST_SAT ? rest : 0n;
      return { utxos: selected, totalIn, amountSat, fee: totalIn - amountSat - change, change, vbytes, feeRateSatVb };
    }
  }

  const fee = BigInt(Math.ceil(estimateTxVBytes(selected.length, sourceType, toAddress, changeAddress) * feeRateSatVb));
  throw new BtcTxError(
    'BTC_INSUFFICIENT_FUNDS',
    `Недостаточно средств. Доступно: ${Number(totalIn) / 1e8} BTC, нужно: ${Number(amountSat + fee) / 1e8} BTC (включая комиссию).`,
  );
}

/**
 * Review estimate in sats with the signer's model. When the balance does not
 * cover the amount, the fee for spending every UTXO is returned (the review
 * reports insufficient funds separately).
 */
export function estimateBtcFeeSat(
  utxos:        UTXO[],
  amountSat:    bigint,
  feeRateSatVb: number,
  fromAddress:  string,
  toAddress?:   string,
): bigint {
  try {
    return planBtcTx(utxos, amountSat, feeRateSatVb, toAddress, fromAddress).fee;
  } catch (e) {
    const code = btcErrorCode(e);
    if (code !== 'BTC_INSUFFICIENT_FUNDS' && code !== 'BTC_NO_UTXO') throw e;
    const sourceType = getSourceType(fromAddress);
    const vbytes = estimateTxVBytes(Math.max(utxos.length, 1), sourceType, toAddress, fromAddress);
    return BigInt(Math.ceil(vbytes * feeRateSatVb));
  }
}

export async function buildSignedTx(
  privKey:       Uint8Array,
  utxos:         UTXO[],
  toAddress:     string,
  changeAddress: string,
  amountSat:     bigint,
  feeRateSat:    number,
): Promise<string> {
  assertBtcFeeRate(feeRateSat);
  const sourceType = getSourceType(changeAddress);
  const signer      = signerFromPrivKey(privKey);
  const payment     = getOwnPayment(signer, sourceType);
  if (!payment.output) throw new Error('Не удалось создать BTC input script.');

  const plan = planBtcTx(utxos, amountSat, feeRateSat, toAddress, changeAddress);
  assertFeeShare(plan.fee, amountSat);
  const psbt = new bitcoin.Psbt({ network: NETWORK });

  for (const utxo of plan.utxos) {
    if (sourceType === 'p2wpkh') {
      psbt.addInput({
        hash: utxo.txid,
        index: utxo.vout,
        witnessUtxo: {
          script: payment.output,
          value: BigInt(utxo.value),
        },
      });
    } else {
      psbt.addInput({
        hash: utxo.txid,
        index: utxo.vout,
        nonWitnessUtxo: await fetchRawTx(utxo.txid),
      });
    }
  }

  psbt.addOutput({ address: toAddress, value: amountSat });
  if (plan.change > 0n) {
    psbt.addOutput({ address: changeAddress, value: plan.change });
  }

  psbt.signAllInputs(signer);
  psbt.finalizeAllInputs();
  return psbt.extractTransaction().toHex();
}

export interface SendBtcOptions {
  /**
   * Fee rate (sat/vB) shown on the review screen. Signing uses exactly this
   * rate (capped). Absent → fetched now, as before, with the same caps.
   */
  feeRateSatVb?: number;
}

/**
 * Decrypt the BTC key, build, sign and broadcast. Same positional parameters
 * as transactions.ts sendBtc plus an optional fee rate. Returns the txid.
 */
export async function sendBtc(
  btcEncBlob:  string,
  password:    string,
  toAddress:   string,
  amountBtc:   number,
  fromAddress: string, // our BTC address (for change output)
  opts:        SendBtcOptions = {},
): Promise<string> {
  // Cheap checks first: no decrypt for a request that can never be signed.
  const amountSat = btcToSats(amountToDecimalString(amountBtc, 8));
  if (amountSat <= BTC_DUST_SAT) throw new BtcTxError('BTC_DUST', 'Сумма ниже минимума (546 sat / dust limit).');
  if (opts.feeRateSatVb !== undefined) assertBtcFeeRate(opts.feeRateSatVb);

  const btcPrivKey = await decryptBytes(btcEncBlob, password);
  try {
    const [utxos, feeRate] = await Promise.all([
      fetchUTXOs(fromAddress),
      opts.feeRateSatVb ?? getBtcFeeRate(),
    ]);
    const rawHex = await buildSignedTx(btcPrivKey, utxos, toAddress, fromAddress, amountSat, feeRate);
    return await broadcastBtcTx(rawHex);
  } finally {
    btcPrivKey.fill(0);
  }
}
